// يتحقق إن الطلب جاي فعلاً من تليجرام (توقيع Ed25519 الرسمي) — من غير ما نحتاج توكن البوت
// التحقق مكتوب بـ JavaScript عادي من غير مكتبة crypto، عشان n8n على الـ VPS قافلها
// ---- Ed25519 verify + SHA-512 in plain JavaScript (BigInt), no Node modules needed ----
const ED = (() => {
  const P = 2n ** 255n - 19n, L = 2n ** 252n + 27742317777372353535851937790883648493n;
  const mod = (a, m = P) => { const r = a % m; return r >= 0n ? r : r + m; };
  const pow = (b, e, m = P) => { let r = 1n; b = mod(b, m); while (e > 0n) { if (e & 1n) r = r * b % m; b = b * b % m; e >>= 1n; } return r; };
  const inv = (a) => pow(a, P - 2n);
  const D = mod(-121665n * inv(121666n));
  const I = pow(2n, (P - 1n) / 4n);
  const add = (p, q) => {
    const [X1, Y1, Z1, T1] = p, [X2, Y2, Z2, T2] = q;
    const A = mod((Y1 - X1) * (Y2 - X2)), B = mod((Y1 + X1) * (Y2 + X2)), C = mod(2n * T1 * T2 * D), Dd = mod(2n * Z1 * Z2);
    const E = B - A, F = Dd - C, G = Dd + C, H = B + A;
    return [mod(E * F), mod(G * H), mod(F * G), mod(E * H)];
  };
  const mul = (s, p) => { let q = [0n, 1n, 1n, 0n]; while (s > 0n) { if (s & 1n) q = add(q, p); p = add(p, p); s >>= 1n; } return q; };
  const le = (b) => { let n = 0n; for (let i = b.length - 1; i >= 0; i--) n = (n << 8n) | BigInt(b[i]); return n; };
  const decode = (b) => {
    const bb = Uint8Array.from(b); const sign = bb[31] >> 7; bb[31] &= 127;
    const y = le(bb); if (y >= P) return null;
    const y2 = y * y % P; const u = mod(y2 - 1n), v = mod(D * y2 + 1n);
    let x = pow(u * inv(v), (P + 3n) / 8n);
    if (mod(x * x - u * inv(v)) !== 0n) x = x * I % P;
    if (mod(x * x - u * inv(v)) !== 0n) return null;
    if (Number(x & 1n) !== sign) x = mod(-x);
    if (x === 0n && sign) return null;
    return [x, y, 1n, x * y % P];
  };
  const encode = (p) => {
    const zi = inv(p[2]); const x = mod(p[0] * zi), y = mod(p[1] * zi);
    const out = new Uint8Array(32); let n = y; for (let i = 0; i < 32; i++) { out[i] = Number(n & 255n); n >>= 8n; }
    if (x & 1n) out[31] |= 128; return out;
  };
  const By = mod(4n * inv(5n));
  const Bp = decode((() => { const o = new Uint8Array(32); let n = By; for (let i = 0; i < 32; i++) { o[i] = Number(n & 255n); n >>= 8n; } return o; })());
  // SHA-512
  const K = ['428a2f98d728ae22','7137449123ef65cd','b5c0fbcfec4d3b2f','e9b5dba58189dbbc','3956c25bf348b538','59f111f1b605d019','923f82a4af194f9b','ab1c5ed5da6d8118','d807aa98a3030242','12835b0145706fbe','243185be4ee4b28c','550c7dc3d5ffb4e2','72be5d74f27b896f','80deb1fe3b1696b1','9bdc06a725c71235','c19bf174cf692694','e49b69c19ef14ad2','efbe4786384f25e3','0fc19dc68b8cd5b5','240ca1cc77ac9c65','2de92c6f592b0275','4a7484aa6ea6e483','5cb0a9dcbd41fbd4','76f988da831153b5','983e5152ee66dfab','a831c66d2db43210','b00327c898fb213f','bf597fc7beef0ee4','c6e00bf33da88fc2','d5a79147930aa725','06ca6351e003826f','142929670a0e6e70','27b70a8546d22ffc','2e1b21385c26c926','4d2c6dfc5ac42aed','53380d139d95b3df','650a73548baf63de','766a0abb3c77b2a8','81c2c92e47edaee6','92722c851482353b','a2bfe8a14cf10364','a81a664bbc423001','c24b8b70d0f89791','c76c51a30654be30','d192e819d6ef5218','d69906245565a910','f40e35855771202a','106aa07032bbd1b8','19a4c116b8d2d0c8','1e376c085141ab53','2748774cdf8eeb99','34b0bcb5e19b48a8','391c0cb3c5c95a63','4ed8aa4ae3418acb','5b9cca4f7763e373','682e6ff3d6b2b8a3','748f82ee5defb2fc','78a5636f43172f60','84c87814a1f0ab72','8cc702081a6439ec','90befffa23631e28','a4506cebde82bde9','bef9a3f7b2c67915','c67178f2e372532b','ca273eceea26619c','d186b8c721c0c207','eada7dd6cde0eb1e','f57d4f7fee6ed178','06f067aa72176fba','0a637dc5a2c898a6','113f9804bef90dae','1b710b35131c471b','28db77f523047d84','32caab7b40c72493','3c9ebe0a15c9bebc','431d67c49c100d4c','4cc5d4becb3e42b6','597f299cfc657e2a','5fcb6fab3ad6faec','6c44198c4a475817'].map((h) => BigInt('0x' + h));
  const M64 = (1n << 64n) - 1n;
  const rotr = (x, n) => ((x >> n) | (x << (64n - n))) & M64;
  const sha512 = (msg) => {
    const len = msg.length; const padLen = ((len + 17 + 127) >> 7) << 7;
    const b = new Uint8Array(padLen); b.set(msg); b[len] = 0x80;
    let bits = BigInt(len) * 8n; for (let i = 0; i < 16; i++) { b[padLen - 1 - i] = Number(bits & 255n); bits >>= 8n; }
    let H = ['6a09e667f3bcc908','bb67ae8584caa73b','3c6ef372fe94f82b','a54ff53a5f1d36f1','510e527fade682d1','9b05688c2b3e6c1f','1f83d9abfb41bd6b','5be0cd19137e2179'].map((h) => BigInt('0x' + h));
    const W = new Array(80);
    for (let o = 0; o < padLen; o += 128) {
      for (let t = 0; t < 16; t++) { let w = 0n; for (let j = 0; j < 8; j++) w = (w << 8n) | BigInt(b[o + t * 8 + j]); W[t] = w; }
      for (let t = 16; t < 80; t++) {
        const s0 = rotr(W[t - 15], 1n) ^ rotr(W[t - 15], 8n) ^ (W[t - 15] >> 7n);
        const s1 = rotr(W[t - 2], 19n) ^ rotr(W[t - 2], 61n) ^ (W[t - 2] >> 6n);
        W[t] = (W[t - 16] + s0 + W[t - 7] + s1) & M64;
      }
      let [a, bq, c, d, e, f, g, h] = H;
      for (let t = 0; t < 80; t++) {
        const S1 = rotr(e, 14n) ^ rotr(e, 18n) ^ rotr(e, 41n), ch = (e & f) ^ (~e & M64 & g);
        const t1 = (h + S1 + ch + K[t] + W[t]) & M64;
        const S0 = rotr(a, 28n) ^ rotr(a, 34n) ^ rotr(a, 39n), mj = (a & bq) ^ (a & c) ^ (bq & c);
        const t2 = (S0 + mj) & M64;
        h = g; g = f; f = e; e = (d + t1) & M64; d = c; c = bq; bq = a; a = (t1 + t2) & M64;
      }
      H = [a, bq, c, d, e, f, g, h].map((v, i) => (H[i] + v) & M64);
    }
    const out = new Uint8Array(64); H.forEach((v, i) => { for (let j = 0; j < 8; j++) out[i * 8 + j] = Number((v >> BigInt(56 - 8 * j)) & 255n); }); return out;
  };
  const verify = (sig, msg, pub) => {
    if (sig.length !== 64 || pub.length !== 32) return false;
    const A = decode(pub), R = decode(sig.slice(0, 32)); if (!A || !R) return false;
    const S = le(sig.slice(32)); if (S >= L) return false;
    const h = mod(le(sha512(Uint8Array.from([...sig.slice(0, 32), ...pub, ...msg]))), L);
    const left = encode(mul(S, Bp)), right = encode(add(R, mul(h, A)));
    return left.every((v, i) => v === right[i]);
  };
  return { verify, sha512 };
})();

// helpers (no Node modules needed)
const hexBytes = (h) => Uint8Array.from(h.match(/../g).map((x) => parseInt(x, 16)));
const utf8 = (s) => { const e = unescape(encodeURIComponent(s)); const o = new Uint8Array(e.length); for (let i = 0; i < e.length; i++) o[i] = e.charCodeAt(i); return o; };
const b64u = (s) => { const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'; s = s.replace(/-/g, '+').replace(/_/g, '/').replace(/=+$/, '');
  const out = []; let buf = 0, bits = 0; for (const ch of s) { const v = A.indexOf(ch); if (v < 0) return new Uint8Array(0); buf = ((buf << 6) | v) & 0xffffff; bits += 6; if (bits >= 8) { bits -= 8; out.push((buf >> bits) & 255); } } return Uint8Array.from(out); };

const BOT_ID = '8922398010';
const TG_PUBLIC_KEY = 'e7bf03a2fa4602af4580703d88dda5bb59f32ed8b02a56c187fe7d34caed242d';
const DEV_KEY = ''; // مفتاح اختبار للمطوّر فقط — سيبه فاضي في التشغيل

const body = $json.body || {};
let req = {};
try { req = typeof body.payload === 'string' ? JSON.parse(body.payload) : (body.payload || body); } catch (e) { req = {}; }
const initData = String(req.initData || '');
let error = '', user = null;

if (DEV_KEY && req.dev_key === DEV_KEY) {
  user = { id: Number(req.dev_tg), first_name: 'dev' };
} else if (!initData) {
  error = 'open_from_telegram';
} else {
  try {
    // تفكيك initData يدويًا (URLSearchParams مش متاح جوه n8n)
    const fields = {};
    initData.split('&').forEach(function (part) {
      if (!part) return;
      const eq = part.indexOf('=');
      const k = decodeURIComponent((eq < 0 ? part : part.slice(0, eq)).replace(/\+/g, ' '));
      const v = eq < 0 ? '' : decodeURIComponent(part.slice(eq + 1).replace(/\+/g, ' '));
      fields[k] = v;
    });
    const sig = fields.signature || '';
    const pairs = [];
    Object.keys(fields).forEach(function (k) { if (k !== 'hash' && k !== 'signature') pairs.push(k + '=' + fields[k]); });
    pairs.sort();
    const check = BOT_ID + ':WebAppData\n' + pairs.join('\n');
    const valid = !!sig && ED.verify(b64u(sig), utf8(check), hexBytes(TG_PUBLIC_KEY));
    const age = Date.now() / 1000 - Number(fields.auth_date || 0);
    if (!valid) error = 'bad_signature';
    else if (age > 7 * 86400) error = 'expired';
    else user = JSON.parse(fields.user || '{}');
  } catch (e) { error = 'bad_init_data'; }
}

const sid = String(req.session_id || '');
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
return [{ json: {
  ok: !error && !!(user && user.id),
  error: error || (user && user.id ? '' : 'no_user'),
  telegram_id: user && user.id ? user.id : 0,
  first_name: (user && user.first_name) || '',
  action: String(req.action || ''),
  topic: String(req.topic || '').slice(0, 120).trim(),
  count: Math.min(10, Math.max(3, Number(req.count) || 5)),
  session_id: UUID.test(sid) ? sid : '00000000-0000-0000-0000-000000000000',
  index: Number(req.index),
  choice: Number(req.choice)
} }];

const s = $('Load Student').first().json;
const r = $input.first().json || {};
const q = r.quiz || {};
return [{ json: { response: {
  ok: true,
  name: s.name,
  grade: s.grade || '',
  group: s.group_name || '',
  weak: (r.weak || []).map(function (w) { return { idea: w.idea, lesson: w.lesson || '', n: Number(w.n) }; }),
  subs: (r.subs || []).map(function (x) { return { code: x.homework_code, score: Number(x.score), total: Number(x.total), date: x.created_at }; }),
  quiz: { count: Number(q.count || 0), correct: Number(q.correct || 0), total: Number(q.total || 0) }
} } }];

const v = $('Verify').first().json;
const general = !v.topic;
const topic = v.topic || 'مراجعة عامة على المنهج';
// البحث في المنهج: المنهج مكتوب بالإنجليزي، فبنضيف كلمات إنجليزي للمراجعة العامة
const query = general ? 'key definitions, laws, properties and calculations' : topic;
return [{ json: { topic: topic, query: query, count: v.count } }];

const t = $('Quiz Topic').first().json;
const MODEL = 'gemini-3.8-flash'; // نفس موديل تصحيح الواجبات
const docs = $input.all().map(function (i) {
  const j = i.json || {};
  return (j.document && j.document.pageContent) || j.pageContent || '';
}).filter(function (d, i, all) { return d && all.indexOf(d) === i; }); // من غير تكرار
const SYSTEM = 'You write multiple-choice practice questions for the students of Mr. Mohammed Hussien, a chemistry/science teacher in Egypt.\n'
  + 'Rules:\n'
  + '- Use ONLY facts found in the curriculum excerpts. Never invent facts or values.\n'
  + '- Write exactly the requested number of questions about the requested topic. If the excerpts do not cover the topic well, use the closest related content in the excerpts. If there are no excerpts, return {"topic":"","questions":[]}.\n'
  + '- Write each question and its options in simple Arabic, keeping scientific terms, formulas, units and numeric values exactly as in the curriculum (English terms may stay in English).\n'
  + '- Exactly 4 options, one correct, plausible distractors, no "all of the above". Vary the position of the correct answer across questions.\n'
  + '- "answer" is the 0-based index of the correct option.\n'
  + '- "explanation": Egyptian Arabic, 1-2 short lines explaining why the correct answer is right.\n'
  + '- "idea": short Arabic name of the tested concept (2-5 words).\n'
  + '- "topic": short Arabic title for this quiz (2-5 words).\n'
  + '- No markdown anywhere.\n'
  + 'Return ONLY valid JSON: {"topic":"","questions":[{"q":"","options":["","","",""],"answer":0,"explanation":"","idea":""}]}';
const user = 'Topic: ' + t.topic + '\nNumber of questions: ' + t.count + '\n\nCurriculum excerpts:\n' + (docs.length ? docs.join('\n---\n') : '(none)');
const body = {
  systemInstruction: { parts: [{ text: SYSTEM }] },
  contents: [{ role: 'user', parts: [{ text: user }] }],
  generationConfig: { temperature: 0.7, maxOutputTokens: 8192, responseMimeType: 'application/json' }
};
return [{ json: { body: body, model: MODEL } }];

const t = $('Quiz Topic').first().json;
const res = $input.first().json || {};
let g = null;
try {
  const parts = (((res.candidates || [])[0] || {}).content || {}).parts || [];
  const txt = parts.filter(function (c) { return c.text && !c.thought; }).map(function (c) { return c.text; }).join('');
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) g = JSON.parse(m[0]);
} catch (e) {}
const qs = ((g && g.questions) || []).filter(function (q) {
  const a = Number(q && q.answer);
  return q && q.q && Array.isArray(q.options) && q.options.length === 4 && Number.isInteger(a) && a >= 0 && a < 4;
}).slice(0, t.count).map(function (q) {
  return { q: String(q.q), options: q.options.map(String), answer: Number(q.answer), explanation: String(q.explanation || ''), idea: String(q.idea || t.topic) };
});
return [{ json: { ok: qs.length > 0, topic: (g && g.topic) || t.topic, questions_json: JSON.stringify(qs), total: qs.length } }];

const p = $('Parse Quiz').first().json;
const qs = JSON.parse(p.questions_json);
return [{ json: { response: {
  ok: true,
  session_id: $input.first().json.id,
  topic: p.topic,
  total: qs.length,
  questions: qs.map(function (q) { return { q: q.q, options: q.options }; })
} } }];

const v = $('Verify').first().json;
const r = $input.first().json || {};
if (!r.id) return [{ json: { skip: true, response: { ok: false, error: 'session_not_found' } } }];
const qs = Array.isArray(r.questions) ? r.questions : [];
const answers = Array.isArray(r.answers) ? r.answers : [];
const i = v.index;
const q = qs[i];
if (!q || !(v.choice >= 0 && v.choice < 4)) return [{ json: { skip: true, response: { ok: false, error: 'bad_answer' } } }];
const prev = answers.find(function (a) { return a.i === i; });
if (prev) {
  return [{ json: { skip: true, response: { ok: true, correct: prev.ok, answer: q.answer, explanation: q.explanation, idea: q.idea, score: r.score, total: r.total, finished: r.finished } } }];
}
const ok = q.answer === v.choice;
const next = answers.concat([{ i: i, c: v.choice, ok: ok }]);
const score = r.score + (ok ? 1 : 0);
const finished = next.length >= r.total;
// الغلطة بتتسجل في جدول mistakes عشان تظهر في "نقط ضعفي" في البوت والمنصة
const mistakes = ok ? [] : [{ question: 'Q' + (i + 1), idea: q.idea, lesson: r.topic, correction: q.options[q.answer] }];
return [{ json: {
  skip: false,
  session_id: r.id,
  answers_json: JSON.stringify(next),
  score: score,
  finished: finished,
  mistakes_json: JSON.stringify(mistakes),
  response: { ok: true, correct: ok, answer: q.answer, explanation: q.explanation, idea: q.idea, score: score, total: r.total, finished: finished }
} }];
